// Order Confirmation Entry
const ctx = $input.item.json;
return [{ json: {
    business_id:  ctx.business_id,
    business_name: ctx.business_name,
    phoneNumber:  ctx.phoneNumber,
    chatId:       ctx.chatId,
    language:     ctx.language,
    messageText:  ctx.messageText
} }];

// Build context for checkout AI
const ctx = $('Order Confirmation Entry').item.json;
const history = $input.all();

const historyText = history.map(m =>
    `[${(m.json.direction || '').toUpperCase()}]: ${m.json.message_text || ''}`
).join('\n');

return [{ json: {
    ...ctx,
    historyText
} }];

// Parse the AI Agent delivery info response
const raw = typeof $input.item.json.output === 'string' ? $input.item.json.output : 
            (typeof $input.item.json.text === 'string' ? $input.item.json.text : JSON.stringify($input.item.json));
const ctx = $('Build Checkout Context').item.json;

let has_delivery = false;
let address = null;
let payment = 'cash_on_delivery';

try {
    // 1. Try to extract standard JSON if the agent obeyed the rules
    const jsonMatch = raw.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        let result = JSON.parse(jsonMatch[0]);
        if (result.action_input && typeof result.action_input === 'string' && result.action_input.includes('{')) {
            result = JSON.parse(result.action_input.match(/\{[\s\S]*\}/)[0]);
        }
        if (result.has_delivery_info === true || result.has_delivery_info === "true") has_delivery = true;
        if (result.delivery_address) address = result.delivery_address;
        if (result.payment_method) payment = result.payment_method;
    }
} catch(e) {}

// 2. Super robust regex fallback for conversational output (e.g. "**Delivery Address:** Samagimawatha")
if (!has_delivery) {
    const rawLower = raw.toLowerCase();
    if (rawLower.includes('delivery address') && (rawLower.includes('payment method') || rawLower.includes('cash on delivery') || rawLower.includes('bank transfer'))) {
        has_delivery = true;

        // Try to regex out the address
        const addrMatch = raw.match(/Delivery Address:\*\*?\s*(.*)/i);
        if (addrMatch) {
            address = addrMatch[1].trim();
        } else {
            // fallback generic regex
            const addrMatch2 = raw.match(/address:?\s*(.*)/i);
            if (addrMatch2) address = addrMatch2[1].trim();
        }

        // Try to regex out the payment
        if (rawLower.includes('bank transfer')) {
            payment = 'bank_transfer';
        } else {
            payment = 'cash_on_delivery'; // default
        }
    }
}

return [{ json: {
    ...ctx,
    has_delivery_info: has_delivery,
    delivery_address: address,
    payment_method: payment
} }];

// Build the order object with delivery details
const ctx = $('Parse Delivery Info').item.json;
const lastQuote = $input.item.json.message_text ?? '';

return [{ json: {
    ...ctx,
    lastQuote,
    items: JSON.stringify([{ product_name: 'Order from chat', qty: 1, unit_price: 0 }]),
    total_price: 0.00,
    discount_applied: 0.00,
    status: 'confirmed'
} }];

